import { useEffect, useRef } from "react";

export function ReportDialog({ open, onClose, children }) {
  const ref = useRef(null);
  useEffect(() => {
    const dialog = ref.current;
    if (open && !dialog.open) dialog.showModal();   // traps focus inside, Escape closes.
    if (!open && dialog.open) dialog.close();
  }, [open]);

  return (
    <dialog ref={ref} aria-labelledby="report-title" onClose={onClose}>
      <h2 id="report-title">Report a problem</h2>
      {children}
      <button type="button" onClick={onClose} aria-label="Close report dialog">×</button>
    </dialog>
  );
}

// Trigger: a real button that exposes its state.
<button type="button" aria-haspopup="dialog" onClick={() => setOpen(true)}>Report a problem</button>
